      var frames = shake ? [T(0), T(1), T(-.8), T(.55), T(-.3), T(.12), T(0)] : [T(0), Object.assign(T(1), { offset: .3 }), Object.assign(T(-.35), { offset: .6 }), T(0)];
      if (ico && ico.animate) ico.animate(frames, { duration: shake ? 600 : 520, delay: dl, easing: shake ? 'ease-out' : 'cubic-bezier(.3,0,.3,1)' });
      if (pr && pr.animate) pr.animate([{ opacity: 0 }, { opacity: .55, offset: .35 }, { opacity: 0 }], { duration: 640, delay: dl, easing: 'ease-out' });
